def get_page(store, limit: int, cursor=None):
    if limit < 1:
        raise ValueError("limit must be positive")
    items = sorted(
        store.all_items(),
        key=lambda item: (item["created_at"], item["item_id"]),
    )
    if cursor is not None:
        cursor_key = tuple(cursor)
        items = [
            item for item in items
            if (item["created_at"], item["item_id"]) > cursor_key
        ]
    return items[:limit]
